```sql
CREATE FUNCTION MutualRecurringElements(
  @tableA TABLE,
  @tableB TABLE,
  @tableC TABLE
)
RETURNS TABLE
AS
RETURN
(
  SELECT 
    t1.column_name AS 'Common Element',
    t2.column_name AS 'Recurring Element',
    t3.column_name AS 'Mutual Recurring Element'
  FROM 
    @tableA t1
  JOIN 
    @tableB t2 ON t1.column_name IN (SELECT column_name FROM t2 WHERE table_name = 'tableB')
  JOIN 
    @tableC t3 ON t2.column_name IN (SELECT column_name FROM t3 WHERE table_name = 'tableC')
  WHERE 
    t1.column_name NOT IN (SELECT column_name FROM t3 WHERE table_name = 'tableC')
);
```
