def change_detection(arr):
    """
    Detects changes in an array of numbers and categorizes them as additions, deletions, or modifications.

    Args:
        arr (list): The input array of numbers.

    Returns:
        dict: A dictionary containing the detected changes, categorized by type (addition, deletion, modification).
    """
    changes = {}
    for i, num in enumerate(arr):
        if num!= arr[i - 1]:
            if num in changes:
                changes[num].append(i)
            else:
                changes[num] = [i]
    return changes

